from collections import deque
def enclosed(g, wall):
    n=len(g); reach=[[False]*n for _ in range(n)]; q=deque()
    for i in range(n):
        for j in range(n):
            if i in(0,n-1) or j in(0,n-1):
                if g[i][j]!=wall and not reach[i][j]: reach[i][j]=True; q.append((i,j))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            r2,c2=r+dr,c+dc
            if 0<=r2<n and 0<=c2<n and not reach[r2][c2] and g[r2][c2]!=wall:
                reach[r2][c2]=True; q.append((r2,c2))
    return [(r,c) for r in range(n) for c in range(n) if not reach[r][c] and g[r][c]!=wall]
